<script setup lang="ts">
import IconButton from './IconButton.vue';
import ImageSettings from './ImageSettings.vue';
import SpeechSettings from './SpeechSettings.vue';
import { useModal } from '../modal';
import { ref,onMounted } from 'vue';import { api,auth,json,logout } from '../api';import type { ModelConfig,McpKey } from '../types';
interface Failure {task_id:string;stage:string;error_type:string;attempts:number;elapsed_ms:number;status:string}
const health=ref<Failure[]>([]);
interface Run {id:string;calls:number;input_tokens:number;output_tokens:number;missing_usage:number;categories:Record<string,{calls:number;input_tokens:number;output_tokens:number}>}
const runs=ref<Run[]>([]),runPage=ref(0);
onMounted(async()=>{try{runs.value=(await api<{runs:Run[]}>('/api/usage')).runs;}catch{}});
const origin=location.origin;
const dialog=ref<HTMLElement>();
const props=defineProps<{world:string;initialTab?:string}>(),emit=defineEmits<{close:[]}>();
const modelTab=ref(props.initialTab==='生图'?'生图':'文字');
const tab=ref(props.initialTab==='生图'?'模型':props.initialTab||'模型'),page=ref(0),status=ref(''),busy=ref(false),loading=ref(true),initiative=ref(false),confirmReset=ref(false),keys=ref<McpKey[]>([]),keyPage=ref(0),newToken=ref('');
const cfg=ref<ModelConfig>({model:'',base_url:'',api_key:'',temperature:1,max_tokens:1500,embedding_model:''});
const current=ref(''),password=ref(''),repeat=ref(''),keyLabel=ref(''),daily=ref(50),tokens=ref(0),days=ref(30),write=ref(true),roles=ref(['wan','yan','liu','group']);
const scope={world:props.world,channel:'group' as const};
async function action(work:()=>Promise<void>){if(busy.value)return;busy.value=true;status.value='正在处理…';try{await work();}catch(e){status.value=(e as Error).message;}finally{busy.value=false;}}
onMounted(async()=>{try{const [model,settings,list,report]=await Promise.all([api<ModelConfig>('/api/home/model'),api<{initiative_enabled:boolean}>('/api/home/settings',{},scope),api<McpKey[]>('/api/mcp/keys'),api<{failures:Failure[]}>('/api/home/task-health',{},scope)]);health.value=report.failures;cfg.value={...model,api_key:''};initiative.value=settings.initiative_enabled;keys.value=list;status.value='';}catch(e){status.value=(e as Error).message;}finally{loading.value=false;}});
function saveModel(){return action(async()=>{const result=await api<ModelConfig>('/api/home/model',{method:'PUT',body:json(cfg.value)});cfg.value={...result,api_key:''};status.value='已保存';});}
function testModel(){return action(async()=>{const result=await api<{model:string}>('/api/home/model/test',{method:'POST',body:json(cfg.value),signal:AbortSignal.timeout(120000)});status.value='连接正常 · '+result.model;});}
function toggleInitiative(){return action(async()=>{const result=await api<{initiative_enabled:boolean}>('/api/home/settings',{method:'PUT',body:json({initiative_enabled:!initiative.value})},scope);initiative.value=result.initiative_enabled;status.value=initiative.value?'主动消息已开启':'主动消息已关闭';});}
function retryTask(){return action(async()=>{const task=health.value[0];await api('/api/home/tasks/'+encodeURIComponent(task.stage)+'/'+encodeURIComponent(task.task_id)+'/retry',{method:'POST'},scope);health.value=(await api<{failures:Failure[]}>('/api/home/task-health',{},scope)).failures;status.value='已重新排队';});}
function reset(){return action(async()=>{await api('/api/home/reset',{method:'POST',body:json({confirm:true})},scope);confirmReset.value=false;status.value='已清除，从当前现实时间重新开始';});}
function changePassword(){return action(async()=>{if(password.value!==repeat.value)throw Error('两次密码不一致');await api('/api/auth/password',{method:'POST',body:json({current_password:current.value,new_password:password.value})});await logout();});}
function createKey(){return action(async()=>{const result=await api<{token:string}>('/api/mcp/keys',{method:'POST',body:json({label:keyLabel.value,scopes:['read',...(write.value?['chat']:[]),...roles.value],daily_limit:daily.value,daily_tokens:tokens.value,days:days.value})});newToken.value=result.token;keys.value=await api<McpKey[]>('/api/mcp/keys');status.value='密钥仅显示这一次，请保存到你的客户端。';});}
function revoke(id:string){return action(async()=>{await api('/api/mcp/keys/'+id,{method:'DELETE'});keys.value=await api<McpKey[]>('/api/mcp/keys');status.value='已撤销';});}
useModal(dialog,()=>emit('close'));
</script>
<template><div class="overlay" @click.self="emit('close')"><section ref="dialog" class="dialog" role="dialog" aria-modal="true" aria-labelledby="homeSettingsTitle"><header><h2 id="homeSettingsTitle">设置</h2><IconButton icon="close" label="关闭设置" @click="emit('close')"/></header><nav class="tabs"><button v-for="name in ['模型','消息','账号','MCP','数据','用量']" :key="name" :class="{active:tab===name}" @click="tab=name;page=0;status=''">{{name}}</button></nav><p class="feedback" role="status" :title="status">{{loading?'正在读取…':status}}</p><div class="dialog-body" v-if="!loading">
<template v-if="tab==='模型'"><nav class="tabs small" aria-label="模型类型"><button v-for="kind in ['文字','生图','语音']" :key="kind" :class="{active:modelTab===kind}" @click="modelTab=kind;page=0;status=''">{{kind}}</button></nav><ImageSettings v-if="modelTab==='生图'"/><SpeechSettings v-else-if="modelTab==='语音'" :world="props.world"/><template v-else><template v-if="page===0"><label>接口地址<input v-model.trim="cfg.base_url" autocomplete="off" placeholder="https://api.example.com/v1"></label><label>模型名称<input v-model.trim="cfg.model" autocomplete="off"></label><label>API Key <small>{{cfg.api_key_masked}}</small><input v-model.trim="cfg.api_key" type="password" autocomplete="new-password" placeholder="留空保留已有密钥"></label></template><template v-else><div class="two-col"><label>回复随机性<input v-model.number="cfg.temperature" type="number" min="0" max="2" step="0.1"></label><label>输出上限（0 不限）<input v-model.number="cfg.max_tokens" type="number" min="0" max="100000"></label></div><label>Embedding 模型（可选）<input v-model.trim="cfg.embedding_model" placeholder="接口支持的向量模型名"></label><p class="muted">不填保留关键词检索；开启会产生额外 Embedding 用量。已有向量会缓存复用。</p></template><nav class="pager"><button @click="page=0" :disabled="page===0">连接</button><button @click="page=1" :disabled="page===1">参数与记忆检索</button></nav></template></template>
<template v-if="tab==='消息'"><label class="switch-row"><span>角色主动消息</span><button class="switch" role="switch" :aria-checked="initiative" @click="toggleInitiative" :disabled="busy"><i/></button></label><p class="muted">关闭后暂停主动联系和角色私下交流，你发消息后仍会正常回复。现实时间继续推进。</p><section v-if="health.length"><h3>后台任务</h3><p class="muted">{{['done','sent','superseded','cancelled'].includes(health[0].status)?'历史异常（已恢复）':'最近异常'}}：{{health[0].stage}} · {{health[0].error_type}} · 第{{health[0].attempts}}次 · {{(health[0].elapsed_ms/1000).toFixed(1)}}秒</p><IconButton v-if="health[0].status==='failed'&&['reply','model_reply','scene','archive','peer_reply','peer_inquiry','peer_followup','action'].includes(health[0].stage)" icon="refresh" label="重试失败任务" @click="retryTask" :busy="busy"/></section></template>
<template v-if="tab==='账号'"><p>{{auth.enabled?'当前账号：'+auth.username:'当前为个人空间，尚未启用账号登录。'}}</p><form v-if="auth.enabled" @submit.prevent="changePassword"><label>当前密码<input v-model="current" type="password" autocomplete="current-password" required maxlength="128"></label><label>新密码<input v-model="password" type="password" autocomplete="new-password" required minlength="10" maxlength="128"></label><label>确认新密码<input v-model="repeat" type="password" autocomplete="new-password" required minlength="10" maxlength="128"></label><button :disabled="busy" class="wide">修改密码并重新登录</button></form></template>
<template v-if="tab==='MCP'"><nav class="tabs small"><button @click="page=0" :class="{active:page===0}">新建授权</button><button @click="page=1" :class="{active:page===1}">已授权客户端</button></nav><template v-if="page===0 && !newToken"><label>客户端名称<input v-model.trim="keyLabel" maxlength="80" placeholder="例如：我的桌面助手"></label><div class="checks"><label v-for="r in ['wan','yan','liu','group']" :key="r"><input v-model="roles" type="checkbox" :value="r">{{({wan:'小婉',yan:'小研',liu:'小柳',group:'群聊'} as Record<string,string>)[r]}}</label><label><input v-model="write" type="checkbox">允许发送消息</label></div><div class="two-col"><label>每日请求上限<input v-model.number="daily" type="number" min="1" max="1000"></label><label>有效期（天）<input v-model.number="days" type="number" min="1" max="365"></label></div><label>每日 Token 预算（0 不限制）<input v-model.number="tokens" type="number" min="0" max="10000000"></label><p class="muted">使用你配置的模型，会消耗你的额度。每个密钥有独立会话，不读取网站里的私人故事。</p><IconButton icon="key" label="生成密钥" @click="createKey" :disabled="busy||!keyLabel||!roles.length" class="primary"/></template><template v-else-if="page===0"><p>接入地址</p><input readonly :value="`${origin}/mcp/`" aria-label="MCP 地址"><label>Authorization: Bearer<input readonly :value="newToken" aria-label="MCP 密钥" @focus="($event.target as HTMLInputElement).select()"></label><p class="muted">使用支持 HTTP＋自定义 Bearer 请求头的 MCP 客户端。密钥只显示一次；此入口不提供 OAuth 自动发现。</p><IconButton icon="check" label="已保存" @click="newToken=''"/></template><template v-else><article v-for="key in keys.slice(keyPage*3,keyPage*3+3)" :key="key.id" class="key-row"><div><strong>{{key.label}}</strong><small>{{key.calls}} / {{key.daily_limit}} 次 · {{key.used_tokens}} Token{{key.estimated_calls?'（含估算）':''}} · {{new Date(key.expires_at*1000).toLocaleDateString()}}</small></div><IconButton :icon="key.revoked?'check':'trash'" :label="key.revoked?'已撤销':'撤销'" @click="revoke(key.id)" :disabled="!!key.revoked||busy"/></article><p v-if="!keys.length" class="muted">尚无授权</p><nav class="pager"><IconButton @click="keyPage--" :disabled="keyPage===0" icon="back" label="上一页"/><IconButton @click="keyPage++" :disabled="(keyPage+1)*3>=keys.length" icon="next" label="下一页"/></nav></template></template>
<template v-if="tab==='用量'"><template v-if="runs[runPage]"><p>{{runs[runPage].id.startsWith('background:')?'后台或未归组调用':'一次发送'}} · {{runs[runPage].calls}} 次模型调用</p><p>输入 {{runs[runPage].input_tokens}} · 输出 {{runs[runPage].output_tokens}} Token</p><p v-if="runs[runPage].missing_usage" class="muted">部分调用未返回用量，合计不完整。</p><article v-for="(value,name) in Object.fromEntries(Object.entries(runs[runPage].categories).slice(page*3,page*3+3))" :key="name"><strong>{{name}}</strong><p>{{value.calls}} 次 · 输入 {{value.input_tokens}} · 输出 {{value.output_tokens}}</p></article><nav class="pager"><IconButton @click="page--" :disabled="page===0" icon="back" label="前项"/><IconButton @click="page++" :disabled="(page+1)*3>=Object.keys(runs[runPage].categories).length" icon="next" label="后项"/></nav><nav class="pager"><IconButton @click="runPage--;page=0" :disabled="runPage===0" icon="back" label="较新"/><IconButton @click="runPage++;page=0" :disabled="runPage+1>=runs.length" icon="next" label="较早"/></nav></template><p v-else class="muted">暂无用量记录</p></template><template v-if="tab==='数据'"><h3>重置聊天和记忆</h3><p class="muted">清除群聊、三人私聊、角色间私聊和全部记忆，从当前现实时间重新开始。保留模型、头像及角色设置。</p><p v-if="confirmReset" class="danger-text">不创建备份，删除后无法撤销。确认继续？</p><div class="actions"><button v-if="confirmReset" @click="confirmReset=false">取消</button><button class="danger" :disabled="busy" @click="confirmReset?reset():confirmReset=true">{{confirmReset?'确认删除并重置':'重置聊天记录'}}</button></div></template>
</div><footer v-if="(tab==='模型'&&modelTab==='文字')||(tab==='账号'&&auth.enabled)"><template v-if="tab==='模型'&&modelTab==='文字'"><IconButton icon="connect" label="测试连接" @click="testModel" :disabled="busy||loading"/><IconButton icon="save" label="保存" @click="saveModel" :disabled="busy||loading" class="primary"/></template><IconButton v-if="tab==='账号'&&auth.enabled" icon="logout" label="退出登录" @click="action(logout)" :disabled="busy"/></footer></section></div></template>
